def build_cartesian(w):
    """按值构建小根堆笛卡尔树（下标即 BST 键）。
    返回 (left[], right[])；下标 0..n-1。"""
    n = len(w)
    left = [-1] * n
    right = [-1] * n
    stk = []
    for i in range(n):
        last = -1
        while stk and w[stk[-1]] > w[i]:
            last = stk.pop()
        if stk:
            right[stk[-1]] = i
        if last != -1:
            left[i] = last
        stk.append(i)
    return left, right, stk[0]

def build_lca_binary_lifting(left, right, root):
    """简单倍增 LCA（仅供自测；竞赛 O(1) 可用欧拉序+ST 表）"""
    n = len(left)
    parent = [-1] * n
    for i in range(n):
        if left[i] != -1:
            parent[left[i]] = i
        if right[i] != -1:
            parent[right[i]] = i
    LOG = max(1, n.bit_length())
    up = [[-1] * n for _ in range(LOG)]
    up[0] = parent[:]
    for k in range(1, LOG):
        for v in range(n):
            mid = up[k - 1][v]
            up[k][v] = up[k - 1][mid] if mid != -1 else -1
    depth = [-1] * n
    stack = [(root, 0)]
    while stack:
        v, d = stack.pop()
        depth[v] = d
        for c in (left[v], right[v]):
            if c != -1:
                stack.append((c, d + 1))
    def lca(a, b):
        if depth[a] < depth[b]:
            a, b = b, a
        diff = depth[a] - depth[b]
        bit = 0
        while diff:
            if diff & 1:
                a = up[bit][a]
            diff >>= 1
            bit += 1
        if a == b:
            return a
        for k in range(LOG - 1, -1, -1):
            if up[k][a] != up[k][b]:
                a = up[k][a]; b = up[k][b]
        return parent[a]
    return lca

def cartesian_rmq_check():
    import random
    for _ in range(50):
        n = random.randint(1, 30)
        a = [random.randint(1, 100) for _ in range(n)]
        left, right, root = build_cartesian(a)
        # 验证 BST 结构：中序遍历 = 原下标顺序
        order = []
        def dfs(u):
            if u == -1:
                return
            dfs(left[u]); order.append(u); dfs(right[u])
        dfs(root)
        assert order == list(range(n))
        # 验证堆性质
        ok = True
        for i in range(n):
            for c in (left[i], right[i]):
                if c != -1 and a[c] < a[i]:
                    ok = False
        assert ok
        # 验证 RMQ 等价性（随机区间）
        lca = build_lca_binary_lifting(left, right, root)
        for _ in range(20):
            l = random.randint(0, n - 1)
            r = random.randint(l, n - 1)
            mn = min(a[l:r + 1])
            got = a[lca(l, r)]
            assert got == mn, (a, l, r, got, mn)
    print('cartesian tree RMQ equivalence OK (50 random cases)')

if __name__ == '__main__':
    left, right, root = build_cartesian([3, 2, 1, 6, 0, 5])
    print('root =', root)
    assert root == 4  # 值 0 最小
    cartesian_rmq_check()
